<?php

namespace Ediligence\EdiligenceBundle\Repository;
Use Doctrine\ORM\Query\Expr\Join;

/**
 * AffecterRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class Tcourrier_iRepository extends \Doctrine\ORM\EntityRepository {

    public function recover_enreg() {
        $qb = $this->createQueryBuilder('m')
              ->select('max(m.numenregistrement) AS max_enreg')   
              ->setMaxResults(1);
        //var_dump($role);
       //var_dump($qb->getQuery());
        return $qb->getQuery()->getOneOrNullResult();
    }
    
    public function registre($service,$mat){
      $qb = $this->createQueryBuilder('c')
                 ->select('c.objet, i.id, i.dateImput, i.delaiImput, c.dateCreat, i.etatTrait, pj')
                 ->innerJoin('EdiligenceBundle:Timputations_i', 'i',  Join::WITH,'c.id = i.courrier')
                 ->innerJoin('EdiligenceBundle:TimputDir_i', 't',  Join::WITH,'i.id = t.imputation')
                 ->leftJoin('AgentBundle:Pj', 'pj',  Join::WITH,'c.piecejointe = pj.id')
                 ->where('i.serviceImput =:serviceImput')
                 ->andWhere('t.imputMatricule=:imputMatricule')
                 ->andWhere('i.etatTrait=:etatTrait')
                 ->setParameter('serviceImput', $service)
                 ->setParameter('imputMatricule', $mat)
                 ->setParameter('etatTrait', 0);
              
      return $qb->getQuery()->getResult();      
    }
   
    public function diligence($service,$mat){
      $qb = $this->createQueryBuilder('c')
                 ->select('c.objet, i.id, i.dateImput, i.delaiImput, c.dateCreat, i.etatTrait, pj')
                 ->innerJoin('EdiligenceBundle:Timputations_i', 'i',  Join::WITH,'c.id = i.courrier')
                 ->innerJoin('EdiligenceBundle:TimputDir_i', 't',  Join::WITH,'i.id = t.imputation')
                 ->leftJoin('AgentBundle:Pj', 'pj',  Join::WITH,'c.piecejointe = pj.id')
                 ->where('t.serviceImput =:serviceImput')
                 ->orWhere('t.serviceImput =:serviceImput1')
                 ->andWhere('i.etatTrait=:etatTrait')
                 ->andWhere('t.matriculeimpute=:imputMatricule')
                 ->setParameter('serviceImput', $service)
                 ->setParameter('serviceImput1', $mat)
                 ->setParameter('imputMatricule', $mat)
                 ->setParameter('etatTrait', 0);
         //dump($qb->getQuery()); die;     
      return $qb->getQuery()->getResult();      
    }
    
   
}
